// This file is not generated by Speakeasy. It exposes the resolved output
// format to hand-written commands that render their own human-readable text
// but must still honour --output-format and agent mode's TOON default.

package output

import "github.com/spf13/cobra"

// Format returns the output format this invocation resolves to: the
// --output-format flag, then the config file, then toon in agent mode, then
// pretty.
func Format(cmd *cobra.Command) string {
	return resolveOutputFormat(cmd)
}
